  s.sbus_elapsed_ = draw.number();
  s.nav_elapsed_ = draw.number();
  s.nav_filtered_ = draw.vector();
  s.nav_seq_ = static_cast<unsigned short>(draw.below(40));
  s.reset_flag_ = draw.flag();
  s.noise_ = draw_Rng(draw);
  s.nav_noise_ = draw_Rng(draw);
  s.heading_noise_ = draw_Rng(draw);
